int findFibonacci(int n) 
{ 
    if (n < 0) 
        return -1; 
    if (n == 0) 
        return 0; 
    if (n == 1) 
        return 1; 

    // base case 
    if (n == 2) 
        return findFibonacci(n - 1) + findFibonacci(n - 2); 

    // recursive case 
    return findFibonacci(n - 1) + findFibonacci(n - 2) + findFibonacci(n - 3); 
} 

